package chatui

const ChattoneStyles = `.chattone{display:contents;min-width:0;max-width:100%;color:var(--hcm-color-text);background:var(--hcm-color-surface)}.chattone[data-ready="false"],.chattone[data-enabled="false"]{display:none}.chattone-menu>summary{display:none;min-height:44px;padding:8px;cursor:pointer}.chattone-choice{position:relative;min-width:0;max-width:100%}.chattone-tooltip{position:absolute;inset-block-end:100%;inset-inline-start:0;z-index:40;width:min(260px,75vw);padding:8px;overflow-wrap:anywhere;background:var(--hcm-color-surface);color:var(--hcm-color-text);border:1px solid var(--hcm-color-border);border-radius:var(--hcm-radius-control);box-shadow:var(--hcm-shadow-raised);visibility:hidden;pointer-events:none}.chattone-choice:hover .chattone-tooltip,.chattone-choice:focus-within .chattone-tooltip{visibility:visible}.chattone-options{z-index:1500;padding:8px;background:var(--hcm-color-surface);border:1px solid var(--hcm-color-border);border-radius:var(--hcm-radius-control);box-shadow:var(--hcm-shadow-raised);overflow:auto}.chattone-options[hidden]{display:none}.chattone-options>[role=group]{display:flex;flex-wrap:wrap;gap:4px}.chattone button:not(.tool-button){min-height:44px;min-width:44px;max-width:100%;padding:8px;border:1px solid var(--hcm-color-border);border-radius:var(--hcm-radius-control);background:var(--hcm-color-surface);color:var(--hcm-color-text);font:inherit;text-align:start;overflow-wrap:anywhere;cursor:pointer}.chattone button:focus-visible,.chattone summary:focus-visible{outline:2px solid var(--hcm-color-focus);outline-offset:2px}.chattone-suggested{display:block;font-size:.75em;min-height:1.5em}.chattone-suggested[data-suggested="false"]{visibility:hidden}.chattone-unavailable{flex:1 1 100%;min-width:0;margin:4px 0;font-size:.8125rem;color:var(--hcm-color-text-muted);overflow-wrap:anywhere}.chattone-unavailable[hidden]{display:none}.chattone-notice{flex:1 1 100%;margin:4px 0;font-size:.8125rem;overflow-wrap:anywhere}.chattone-status{flex:1 1 100%;block-size:6em;overflow:auto;font-size:.8125rem;overflow-wrap:anywhere}.chattone-preview-actions{display:flex;flex-wrap:wrap;gap:4px}.chattone-diff{flex:1 1 100%;min-width:0;max-width:100%;white-space:pre-wrap;overflow-wrap:anywhere}.chattone-diff p{margin:4px 0}.chattone-diff del,.chattone-diff ins{display:block}.chat-workspace .composer-tools{flex-wrap:wrap;min-width:0}.chattone-preview{flex:1 1 100%}.chattone-preview:empty{display:none}@media(max-width:600px){.chattone-options>[role=group]{flex-direction:column}}@media(prefers-reduced-motion:reduce){.chattone *{animation:none;transition:none}}` + ChattoneRewordStyles
